   public static BlockPos findCenterBlock(Level level, BlockPos pos) {
      for(MagicCenterBlockEntity center : MagicCenterBlockEntity.getLoadedCentersNear(level, pos, 303)) {
         BlockPos centerPos = center.getBlockPos();
         int dx = centerPos.getX() - pos.getX();
         int dy = centerPos.getY() - pos.getY();
         int dz = centerPos.getZ() - pos.getZ();
         double radius = (double)center.getRadius() + (double)0.5F;
         if (Math.abs(dy) <= 1 && center.isBlank() && (double)(dx * dx + dz * dz) <= radius * radius) {
            return centerPos;
         }
      }

      return null;
   }

   public BlockPos findOwningCenter() {
      if (this.level == null) {
         return null;
      } else {
         long gameTime = this.level.getGameTime();
         if (this.cachedCenterPos != null) {
            BlockEntity var4 = this.level.getBlockEntity(this.cachedCenterPos);
            if (var4 instanceof MagicCenterBlockEntity) {
               MagicCenterBlockEntity center = (MagicCenterBlockEntity)var4;
               if (center.isBlank() && Vec3.atCenterOf(this.worldPosition).distanceToSqr(center.centerPoint()) <= (double)(center.getRadius() * center.getRadius())) {
                  return this.cachedCenterPos;
               }
            }
         }

         if (gameTime < this.nextCenterLookupTick) {
            return null;
         } else {
            this.nextCenterLookupTick = gameTime + 40L;
            this.cachedCenterPos = findCenterBlock(this.level, this.worldPosition);
            return this.cachedCenterPos;
         }
      }
   }

   private static int countSameTypeCircles(Level level, BlockPos centerPos, int radius, CircleType type) {
      int count = 0;

      for(int x = -radius; x <= radius; ++x) {
         for(int z = -radius; z <= radius; ++z) {
            double hDist = Math.sqrt((double)(x * x + z * z));
            if (!(hDist > (double)radius + (double)0.5F)) {
               for(int y = -1; y <= 1; ++y) {
                  BlockPos checkPos = centerPos.offset(x, y, z);
                  BlockState state = level.getBlockState(checkPos);
                  if (state.is((Block)ModBlocks.MAGIC_CIRCLE_BLOCK.get()) && state.getValue(MagicCircleBlock.CIRCLE_TYPE) == type && !ComboBlockEntity.isCirclePartOfActiveCombo(level, checkPos)) {
                     ++count;
                  }
               }
            }
         }
      }

      return count;
   }
